    ("POST", P + "/stickers", lambda h, q, eid: (lambda b: service.give_sticker(int(eid), b["sticker"], b.get("message", ""), b.get("giver", "엄마")))(J(h))),
    ("POST", P + r"/items/(\d+)/skip", lambda h, q, eid, iid: service.set_skipped(int(eid), int(iid), bool(J(h).get("skipped", True)))),
    ("GET", P + "/return", lambda h, q, eid: service.return_view(int(eid))),
    ("POST", P + "/return", lambda h, q, eid: (lambda b: service.set_returned(int(eid), int(b["item_id"]), bool(b.get("returned", True))))(J(h))),
    ("POST", P + "/return/report", lambda h, q, eid: service.return_report(int(eid))),
    ("GET", P + "/tones", lambda h, q, eid: service.tone_previews(int(eid))),
]


# ---------- 소켓 없이 같은 주소표 부르기(브라우저 안 실행과 시험에서 쓴다) ----------
class MemoryRequest:
    """HTTP 요청 대신 넘기는 껍데기. 사진 파일은 이름만 받고 내용은 받지 않는다."""

    def __init__(self, json_body=None, fields=None, files=None):
        self._j, self._fields, self._files = json_body, dict(fields or {}), list(files or [])

    def _body(self) -> bytes:
        return b""

    def _json(self) -> dict:
        return self._j if isinstance(self._j, dict) else {}

    def _form(self) -> tuple[dict, list]:
        return self._fields, self._files


def dispatch(method: str, path: str, query: dict | None = None, json_body=None, fields=None, files=None) -> tuple[int, object]:
    """서버를 띄우지 않고 /api/ 주소를 부른다. (상태 번호, 돌려줄 값)을 준다."""
    req = MemoryRequest(json_body, fields, files)
    try:
        for m, pattern, fn in ROUTES:
            hit = re.fullmatch(pattern, path)
            if m == method and hit and pattern.startswith("/api/"):
                out = fn(req, query or {}, *hit.groups())
                return (404, {"detail": "찾을 수 없어요"}) if out is None else (200, out)
        return 404, {"detail": "없는 주소예요"}
    except (ValueError, KeyError, TypeError, json.JSONDecodeError) as e:
        return 400, {"detail": f"요청을 읽지 못했어요: {e}"}
    except Exception as e:
        return 500, {"detail": f"서버 오류: {type(e).__name__}"}


def boot(reset: bool = False):
    """저장소를 준비하고 예시 일정을 넣는다. reset 이면 처음 상태로 되돌린다."""
    if reset and os.path.exists(db.DB_PATH):
        os.remove(db.DB_PATH)
    db.init()
    service.init()
    seed()


def main():
    boot()
    port = int(os.environ.get("PORT", "6111"))
    srv = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    print(f"가방쏙 예시 서버: http://127.0.0.1:{port}  (끄려면 Ctrl+C) · DB {os.environ['DB_PATH']}", flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

app/db.py:
"""SQLite 저장소. 캘린더 MCP 서버와 웹 API 가 같은 DB 를 씁니다."""
import json
import os
import sqlite3
from contextlib import contextmanager

DB_PATH = os.environ.get("DB_PATH", "/data/app.db")

SCHEMA = """
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'event',          -- event | deadline | etc
  date TEXT NOT NULL,                          -- YYYY-MM-DD
  start_time TEXT, end_time TEXT,              -- HH:MM
  location TEXT, lat REAL, lon REAL,
  outdoor INTEGER NOT NULL DEFAULT 0,
  target TEXT, notes TEXT,
  source_title TEXT, source_url TEXT,
  weather_json TEXT, weather_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'notice',       -- notice | ai | weather | user
  reason TEXT,
  checked INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,                          -- eve | morning | test
  fire_at TEXT NOT NULL,                       -- YYYY-MM-DD HH:MM (KST)
  message TEXT,
  delivered_at TEXT,
  UNIQUE(event_id, kind)
);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
"""


def connect() -> sqlite3.Connection:
    os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys = ON")
    return con


@contextmanager
def tx():
    con = connect()
    try:
        yield con
        con.commit()
    finally:
        con.close()


def init():
    with tx() as con:
        con.executescript(SCHEMA)
        con.execute(
            "INSERT OR IGNORE INTO settings(key,value) VALUES('home', ?)",
            (json.dumps({"name": "성남시 분당구", "lat": 37.3827, "lon": 127.1189}, ensure_ascii=False),),
        )


def get_setting(key: str, default=None):
    with tx() as con:
        row = con.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return json.loads(row["value"]) if row else default


def set_setting(key: str, value):
    with tx() as con:
        con.execute(
            "INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
            (key, json.dumps(value, ensure_ascii=False)),
        )


def event_dict(con, row) -> dict:
    ev = dict(row)
    ev["outdoor"] = bool(ev["outdoor"])
    ev["weather"] = json.loads(ev.pop("weather_json") or "null")
    ev["items"] = [
        dict(r) | {"checked": bool(r["checked"])}
        for r in con.execute("SELECT * FROM items WHERE event_id=? ORDER BY id", (ev["id"],))
    ]
    return ev


def list_events(start: str | None = None, end: str | None = None) -> list[dict]:
    q, args = "SELECT * FROM events WHERE 1=1", []
    if start:
        q += " AND date >= ?"; args.append(start)
    if end:
        q += " AND date <= ?"; args.append(end)
    q += " ORDER BY date, COALESCE(start_time,'99:99'), id"
    with tx() as con:
        return [event_dict(con, r) for r in con.execute(q, args).fetchall()]


def get_event(event_id: int) -> dict | None:
    with tx() as con:
        row = con.execute("SELECT * FROM events WHERE id=?", (event_id,)).fetchone()
        return event_dict(con, row) if row else None


EVENT_FIELDS = ["title", "kind", "date", "start_time", "end_time", "location", "lat", "lon",
                "outdoor", "target", "notes", "source_title", "source_url"]


def insert_event(data: dict, items: list[dict]) -> int:
    vals = {k: data.get(k) for k in EVENT_FIELDS}
    vals["outdoor"] = 1 if vals.get("outdoor") else 0
    vals["kind"] = vals.get("kind") or "event"
    with tx() as con:
        cur = con.execute(
            f"INSERT INTO events({','.join(vals)}) VALUES({','.join('?' * len(vals))})",
            list(vals.values()),
        )
        eid = cur.lastrowid
        for it in items:
            con.execute(
                "INSERT INTO items(event_id,name,source,reason) VALUES(?,?,?,?)",
                (eid, it["name"], it.get("source", "notice"), it.get("reason")),
            )
    return eid


def update_event(event_id: int, data: dict):
    vals = {k: data[k] for k in EVENT_FIELDS if k in data}
    if "outdoor" in vals:
        vals["outdoor"] = 1 if vals["outdoor"] else 0
    if not vals:
        return
    with tx() as con:
        con.execute(
            f"UPDATE events SET {','.join(f'{k}=?' for k in vals)} WHERE id=?",
            [*vals.values(), event_id],
        )


def delete_event(event_id: int) -> bool:
    with tx() as con:
        return con.execute("DELETE FROM events WHERE id=?", (event_id,)).rowcount > 0


def add_item(event_id: int, name: str, source="user", reason=None) -> int:
    with tx() as con:
        return con.execute(
            "INSERT INTO items(event_id,name,source,reason) VALUES(?,?,?,?)",
            (event_id, name, source, reason),
        ).lastrowid


def set_item_checked(item_id: int, checked: bool):
    with tx() as con:
        con.execute("UPDATE items SET checked=? WHERE id=?", (1 if checked else 0, item_id))


def delete_item(item_id: int):
    with tx() as con:
        con.execute("DELETE FROM items WHERE id=?", (item_id,))


def replace_weather(event_id: int, weather: dict | None, items: list[dict], fetched_at: str):
    """날씨 준비물은 매번 다시 계산. 같은 이름이면 체크 상태를 유지."""
    with tx() as con:
        prev = {r["name"]: r["id"] for r in con.execute(
            "SELECT id, name FROM items WHERE event_id=? AND source='weather'", (event_id,))}
        keep = set()
        for it in items:
            if it["name"] in prev:        # 같은 이름은 같은 줄을 고쳐 쓴다(번호와 체크 유지)
                con.execute("UPDATE items SET reason=? WHERE id=?", (it["reason"], prev[it["name"]]))
                keep.add(prev[it["name"]])
            else:
                con.execute(
                    "INSERT INTO items(event_id,name,source,reason,checked) VALUES(?,?, 'weather', ?, 0)",
                    (event_id, it["name"], it["reason"]),
                )
        for name, iid in prev.items():
            if iid not in keep:
                con.execute("DELETE FROM items WHERE id=?", (iid,))
        con.execute(
            "UPDATE events SET weather_json=?, weather_at=? WHERE id=?",
            (json.dumps(weather, ensure_ascii=False) if weather else None, fetched_at, event_id),
        )

app/reminders.py:
"""알림 예약과 메시지 생성.

일정마다 두 번 알림: 전날 19:00(가방 싸기) · 당일 07:30(마지막 확인 + 날씨).
마감(deadline) 일정은 전날 19:00 · 당일 08:30.
메시지는 발송 시점에 만들어서 최신 날씨·체크 상태를 반영합니다.
"""
from datetime import date as Date, datetime, timedelta

from . import db

EVE_AT = "19:00"
MORNING_AT = {"event": "07:30", "deadline": "08:30", "etc": "07:30"}


def now_str() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def schedule_for_event(event_id: int):
    ev = db.get_event(event_id)
    if not ev:
        return
    d = Date.fromisoformat(ev["date"])
    plan = {
        "eve": f"{(d - timedelta(days=1)).isoformat()} {EVE_AT}",
        "morning": f"{d.isoformat()} {MORNING_AT.get(ev['kind'], '07:30')}",
    }
    now = now_str()
    with db.tx() as con:
        con.execute("DELETE FROM notifications WHERE event_id=? AND kind IN ('eve','morning') AND delivered_at IS NULL",
                    (event_id,))
        for kind, at in plan.items():
            if at > now:
                con.execute("INSERT OR IGNORE INTO notifications(event_id,kind,fire_at) VALUES(?,?,?)",
                            (event_id, kind, at))


def build_message(ev: dict, kind: str) -> tuple[str, str]:
    left = [i["name"] for i in ev["items"] if not i["checked"]]
    w = ev.get("weather") or {}
    wx = ""
    if w.get("status") == "ok":
        p = w.get("rain_prob_window") if w.get("rain_prob_window") is not None else w.get("rain_prob")
        wx = f" · {w['weather']}" + (f" {p}%" if p is not None else "")
        if w.get("pm10_grade"):
            wx += f" · 미세먼지 {max(w['pm10_grade'], w.get('pm25_grade') or '좋음', key=['좋음','보통','나쁨','매우나쁨'].index)}"
    gap = (Date.fromisoformat(ev["date"]) - Date.today()).days
    when = {0: "오늘", 1: "내일"}.get(gap, f"{ev['date'][5:].replace('-', '/')}")
    if ev["kind"] == "deadline":
        title = f"📮 {when}까지: {ev['title']}"
    else:
        title = f"🎒 {when} {ev['title']}{wx}"
    if left:
        body = "챙길 것: " + ", ".join(left)
    else:
        body = "준비물 모두 챙겼어요 👍"
    if kind == "morning" and ev.get("start_time"):
        body = f"{ev['start_time']} 시작 · " + body
    return title, body


def due_notifications() -> list[dict]:
    """fire_at 이 지난 미발송 알림을 꺼내 메시지를 채우고 발송 처리."""
    now = now_str()
    out = []
    with db.tx() as con:
        rows = con.execute(
            "SELECT * FROM notifications WHERE delivered_at IS NULL AND fire_at <= ? ORDER BY fire_at", (now,)
        ).fetchall()
    for r in rows:
        ev = db.get_event(r["event_id"])
        if not ev:
            continue
        if r["kind"] in ("kid", "home") and r["message"]:
            title, _, body = r["message"].partition("\n")
        else:
            title, body = build_message(ev, "eve" if r["kind"] == "eve" else "morning")
        with db.tx() as con:
            con.execute("UPDATE notifications SET delivered_at=?, message=? WHERE id=?",
                        (now, f"{title}\n{body}", r["id"]))
        out.append({"id": r["id"], "event_id": r["event_id"], "title": title, "body": body, "fire_at": r["fire_at"]})
    return out


def fire_test(event_id: int) -> dict | None:
    ev = db.get_event(event_id)
    if not ev:
        return None
    with db.tx() as con:
        con.execute("DELETE FROM notifications WHERE event_id=? AND kind='test'", (event_id,))
        con.execute("INSERT INTO notifications(event_id,kind,fire_at) VALUES(?, 'test', ?)", (event_id, now_str()))
    return {"ok": True}


def history(limit=30) -> list[dict]:
    with db.tx() as con:
        return [dict(r) for r in con.execute(
            "SELECT n.*, e.title AS event_title, e.date AS event_date FROM notifications n "
            "JOIN events e ON e.id=n.event_id ORDER BY n.fire_at DESC LIMIT ?", (limit,))]


def kid_report(event_id: int) -> dict | None:
    """아이가 '엄마에게 보여 주기'를 누르면 보호자 알림으로 결과를 보냄."""
    ev = db.get_event(event_id)
    if not ev:
        return None
    done = [i["name"] for i in ev["items"] if i["checked"]]
    left = [i["name"] for i in ev["items"] if not i["checked"]]
    title = f"🧒 아이가 가방을 쌌어요 · {ev['title']}"
    body = f"넣음 {len(done)} · 아직 {len(left)}" + (f" ({', '.join(left)})" if left else " — 다 챙겼어요!")
    with db.tx() as con:
        con.execute("DELETE FROM notifications WHERE event_id=? AND kind='kid'", (event_id,))
        con.execute("INSERT INTO notifications(event_id,kind,fire_at,message) VALUES(?, 'kid', ?, ?)",
                    (event_id, now_str(), f"{title}\n{body}"))
    return {"title": title, "body": body, "done": done, "left": left}

app/weather.py:
"""Open-Meteo(키 불필요)로 일정 당일 날씨·미세먼지를 보고 준비물을 추천.

- 강수: 일 최대 강수확률 / 강수량
- 미세먼지: 행사 시간대(없으면 08~18시) PM10·PM2.5 최댓값, 환경부 등급 기준
"""
from datetime import date as Date, datetime, timedelta

import httpx

FORECAST = "https://api.open-meteo.com/v1/forecast"
METNO = "https://api.met.no/weatherapi/locationforecast/2.0/complete"   # 폴백 (약 9일)
UA = {"User-Agent": "school-notice-helper-poc/0.1"}
AIR = "https://air-quality-api.open-meteo.com/v1/air-quality"
FORECAST_DAYS = 16   # 날씨 예보 범위
AIR_DAYS = 5         # 미세먼지 예보 범위

# 환경부 통합 예보 등급 (㎍/㎥)
PM10_GRADES = [(30, "좋음"), (80, "보통"), (150, "나쁨"), (10**9, "매우나쁨")]
PM25_GRADES = [(15, "좋음"), (35, "보통"), (75, "나쁨"), (10**9, "매우나쁨")]
GRADE_RANK = {"좋음": 0, "보통": 1, "나쁨": 2, "매우나쁨": 3}

WMO = {0: "맑음", 1: "대체로 맑음", 2: "구름 조금", 3: "흐림", 45: "안개", 48: "안개",
       51: "약한 이슬비", 53: "이슬비", 55: "강한 이슬비", 61: "약한 비", 63: "비", 65: "강한 비",
       66: "어는 비", 67: "어는 비", 71: "약한 눈", 73: "눈", 75: "강한 눈", 77: "싸락눈",
       80: "소나기", 81: "소나기", 82: "강한 소나기", 85: "눈 소나기", 86: "눈 소나기",
       95: "뇌우", 96: "뇌우(우박)", 99: "뇌우(우박)"}


def grade(v, table):
    if v is None:
        return None
    for limit, name in table:
        if v <= limit:
            return name


def _hours(start_time: str | None, end_time: str | None) -> tuple[int, int]:
    s = int(start_time[:2]) if start_time else 8
    e = int(end_time[:2]) if end_time else max(s + 1, 18)
    return s, max(e, s)


async def fetch_outlook(lat: float, lon: float, day: str, start_time=None, end_time=None) -> dict | None:
    d = Date.fromisoformat(day)
    ahead = (d - Date.today()).days
    if ahead < 0:
        return {"status": "past"}
    if ahead >= FORECAST_DAYS:
        return {"status": "too_far", "days_ahead": ahead, "available_from": FORECAST_DAYS - 1}

    out = {"status": "ok", "date": day, "lat": lat, "lon": lon}
    s, e = _hours(start_time, end_time)
    async with httpx.AsyncClient(timeout=10, headers=UA) as c:
        try:
            out.update(await _open_meteo(c, lat, lon, day, s, e))
        except httpx.HTTPError:
            if ahead > 9:
                return {"status": "too_far", "days_ahead": ahead, "available_from": 9}
            out.update(await _metno(c, lat, lon, day, s, e))

        if ahead < AIR_DAYS:
            r = await c.get(AIR, params={
                "latitude": lat, "longitude": lon, "timezone": "Asia/Seoul",
                "start_date": day, "end_date": day, "hourly": "pm10,pm2_5",
            })
            if r.status_code == 200:
                h = r.json()["hourly"]
                win = [i for i, t in enumerate(h["time"]) if s <= int(t[11:13]) <= e]
                pm10 = [h["pm10"][i] for i in win if h["pm10"][i] is not None]
                pm25 = [h["pm2_5"][i] for i in win if h["pm2_5"][i] is not None]
                out["pm10"] = round(max(pm10)) if pm10 else None
                out["pm25"] = round(max(pm25)) if pm25 else None
        else:
            out["air_note"] = f"미세먼지 예보는 {AIR_DAYS}일 전부터 확인돼요"
    out["pm10_grade"] = grade(out.get("pm10"), PM10_GRADES)
    out["pm25_grade"] = grade(out.get("pm25"), PM25_GRADES)
    out["fetched_at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
    return out


async def _open_meteo(c, lat, lon, day, s, e) -> dict:
    r = await c.get(FORECAST, timeout=5, params={
        "latitude": lat, "longitude": lon, "timezone": "Asia/Seoul",
        "start_date": day, "end_date": day,
        "daily": "weather_code,precipitation_probability_max,precipitation_sum,temperature_2m_max,temperature_2m_min",
        "hourly": "precipitation_probability",
    })
    r.raise_for_status()
    j = r.json()
    dd = j["daily"]
    hp = [p for t, p in zip(j["hourly"]["time"], j["hourly"]["precipitation_probability"])
          if p is not None and s <= int(t[11:13]) <= e]
    return {
        "provider": "Open-Meteo",
        "weather": WMO.get(dd["weather_code"][0], "-"),
        "rain_prob": dd["precipitation_probability_max"][0],
        "rain_prob_window": max(hp) if hp else None,
        "rain_mm": dd["precipitation_sum"][0],
        "t_max": dd["temperature_2m_max"][0],
        "t_min": dd["temperature_2m_min"][0],
    }


METNO_KO = [("thunder", "뇌우"), ("sleet", "진눈깨비"), ("heavysnow", "강한 눈"), ("snow", "눈"),
            ("heavyrain", "강한 비"), ("lightrain", "약한 비"), ("rain", "비"), ("fog", "안개"),
            ("cloudy", "흐림"), ("partlycloudy", "구름 조금"), ("fair", "대체로 맑음"), ("clearsky", "맑음")]


def _ko(sym: str | None) -> str:
    for k, v in METNO_KO:
        if sym and k in sym:
            return v
    return "-"


async def _metno(c, lat, lon, day, s, e) -> dict:
    """MET Norway: 시각별 강수량·기호로 확률 대신 '비 신호'를 만든다."""
    r = await c.get(METNO, params={"lat": round(lat, 4), "lon": round(lon, 4)})
    r.raise_for_status()
    temps, mm, win_mm, syms, win_syms = [], 0.0, 0.0, [], []
    for t in r.json()["properties"]["timeseries"]:
        kst = datetime.fromisoformat(t["time"].replace("Z", "+00:00")) + timedelta(hours=9)
        if kst.date().isoformat() != day:
            continue
        d = t["data"]
        temps.append(d["instant"]["details"]["air_temperature"])
        nxt = d.get("next_1_hours") or d.get("next_6_hours") or {}
        amt = (nxt.get("details") or {}).get("precipitation_amount") or 0
        sym = (nxt.get("summary") or {}).get("symbol_code")
        hrs = 1 if "next_1_hours" in d else 6
        mm += amt
        syms.append(sym)
        if kst.hour <= e and kst.hour + hrs > s:
            win_mm += amt; win_syms.append(sym)
    wet = [x for x in win_syms if x and any(k in x for k in ("rain", "sleet", "snow", "thunder"))]
    main = max(set(win_syms or syms), key=(win_syms or syms).count) if (win_syms or syms) else None
    return {
        "provider": "MET Norway",
        "weather": _ko(wet[0] if wet else main),
        "rain_prob": None, "rain_prob_window": None,
        "rain_mm": round(mm, 1), "rain_mm_window": round(win_mm, 1),
        "rain_signal": "rain" if win_mm >= 0.5 or len(wet) >= 2 else ("maybe" if wet or win_mm > 0 else "none"),
        "t_max": max(temps) if temps else None,
        "t_min": min(temps) if temps else None,
    }


def recommend(o: dict | None, outdoor: bool) -> list[dict]:
    """날씨 → 준비물. [{name, reason}]"""
    if not o or o.get("status") != "ok":
        return []
    items = []
    prob = o.get("rain_prob_window") if o.get("rain_prob_window") is not None else o.get("rain_prob")
    mm = o.get("rain_mm") or 0
    snow = "눈" in (o.get("weather") or "")
    if prob is not None:
        level = "rain" if prob >= 60 or mm >= 1 else "maybe" if prob >= 30 else "none"
        why = f"{o['weather']} · 강수확률 {prob}% · 예상 {mm}mm"
    else:  # 확률이 없는 예보(MET Norway)
        level = o.get("rain_signal", "none")
        why = f"{o['weather']} · 활동 시간 강수 {o.get('rain_mm_window', mm)}mm 예보"
    if level == "rain":
        items.append({"name": "우산", "reason": why})
        if outdoor:
            items.append({"name": "우비·여벌 양말", "reason": "야외 활동인데 비 예보가 있어요"})
    elif level == "maybe":
        items.append({"name": "접이식 우산", "reason": why + " — 혹시 모르니 가방에"})
    if snow and not any(i["name"] == "우산" for i in items):
        items.append({"name": "우산", "reason": f"{o['weather']} 예보"})

    g = max([x for x in (o.get("pm10_grade"), o.get("pm25_grade")) if x] or ["좋음"], key=GRADE_RANK.get)
    if GRADE_RANK[g] >= 2:
        mask = "KF94 마스크" if g == "매우나쁨" else "KF80 마스크"
        items.append({"name": mask, "reason": f"미세먼지 {g} (PM10 {o.get('pm10')}, PM2.5 {o.get('pm25')}㎍/㎥)"})

    tmin, tmax = o.get("t_min"), o.get("t_max")
    if tmin is not None and tmin <= 0 and outdoor:
        items.append({"name": "장갑·핫팩", "reason": f"최저 {tmin}°C — 야외 활동이라 추워요"})
    elif tmin is not None and tmin <= 5:
        items.append({"name": "따뜻한 겉옷", "reason": f"최저 {tmin}°C"})
    if tmax is not None and tmax >= 30 and outdoor:
        items.append({"name": "모자·여분 물", "reason": f"최고 {tmax}°C — 더위 대비"})
    return items

app/chaeng/calendar_out.py:
"""가방쏙 일정을 바깥 캘린더(구글·애플·삼성 등)로 내보낸다. 계정 연결(OAuth) 없이 링크와 파일(.ics)로 넘긴다.

- entry(): 제목·메모(말투 3가지)·시작/끝·알림 시각을 한 묶음으로
- google_url(): 구글 캘린더의 '일정 만들기' 화면을 채워서 여는 주소(저장은 사람이 누른다)
- to_ics(): 캘린더 파일(RFC 5545). 알림은 전날 19:00, 당일 아침(본체 알림과 같은 시각)
시각은 한국 시간(UTC+9, 서머타임 없음)으로 보고 UTC 로 적는다.
"""
from __future__ import annotations

import urllib.parse
from datetime import date as Date, datetime, timedelta, timezone

from . import tone

KST = timedelta(hours=9)
EVE_AT = "19:00"
MORNING_AT = {"event": "07:30", "deadline": "08:30", "etc": "07:30"}


def _dt(day: str, hhmm: str) -> datetime:
    return datetime.fromisoformat(f"{day}T{hhmm}:00")


def entry(view: dict, tone_key: str = "basic") -> dict:
    """달력에 넣을 한 건. view 는 service.view() 결과."""
    if tone_key not in tone.TONES:
        tone_key = "basic"
    title, body = tone.calendar_entry(view, tone_key)
    day, start, end = view["date"], view.get("start_time"), view.get("end_time")
    all_day = not start
    prev = (Date.fromisoformat(day) - timedelta(days=1)).isoformat()
    return {
        "tone": tone_key, "title": title, "description": body, "location": view.get("location") or "",
        "date": day, "all_day": all_day,
        "start": None if all_day else f"{day}T{start}:00+09:00",
        "end": None if all_day else f"{day}T{end or start}:00+09:00",
        "reminders": [
            {"at": f"{prev}T{EVE_AT}:00+09:00", "text": f"내일 {view['title']}: 가방 싸기"},
            {"at": f"{day}T{MORNING_AT.get(view.get('kind'), '07:30')}:00+09:00", "text": f"오늘 {view['title']}: 마지막 확인"},
        ],
    }


def _utc(local: datetime) -> str:
    return (local - KST).strftime("%Y%m%dT%H%M%SZ")


def _span(e: dict) -> tuple[datetime, datetime]:
    """시작과 끝(한국 시간). 하루 종일이면 그날 0시부터 다음 날 0시."""
    if e["all_day"]:
        s = _dt(e["date"], "00:00")
        return s, s + timedelta(days=1)
    s = datetime.fromisoformat(e["start"][:19])
    t = datetime.fromisoformat(e["end"][:19])
    return s, (t if t > s else s + timedelta(hours=1))


def google_url(e: dict) -> str:
    s, t = _span(e)
    dates = f"{s:%Y%m%d}/{t:%Y%m%d}" if e["all_day"] else f"{_utc(s)}/{_utc(t)}"
    q = {"action": "TEMPLATE", "text": e["title"], "dates": dates, "details": e["description"], "ctz": "Asia/Seoul"}
    if e["location"]:
        q["location"] = e["location"]
    return "https://calendar.google.com/calendar/render?" + urllib.parse.urlencode(q)


def _esc(text: str) -> str:
    return text.replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,").replace("\r", "").replace("\n", "\\n")


def _fold(line: str) -> str:
    """한 줄을 75바이트 안으로 접는다(글자 중간은 자르지 않는다)."""
    out, cur, size = [], "", 0
    for ch in line:
        n = len(ch.encode("utf-8"))
        if size + n > 73:
            out.append(cur)
            cur, size = " ", 1
        cur += ch
        size += n
    return "\r\n".join(out + [cur])


def _trigger(alarm: datetime, start: datetime) -> str:
    mins = int((alarm - start).total_seconds() // 60)
    sign, mins = ("-" if mins < 0 else ""), abs(mins)
    return f"{sign}PT{mins // 60}H{mins % 60}M" if mins % 60 else f"{sign}PT{mins // 60}H"


def to_ics(e: dict, uid: str, now: datetime | None = None) -> str:
    s, t = _span(e)
    stamp = (now or datetime.now(timezone.utc)).strftime("%Y%m%dT%H%M%SZ")
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//gabangssok//bag-check//KO", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
             "BEGIN:VEVENT", f"UID:{uid}", f"DTSTAMP:{stamp}"]
    if e["all_day"]:
        lines += [f"DTSTART;VALUE=DATE:{s:%Y%m%d}", f"DTEND;VALUE=DATE:{t:%Y%m%d}"]
    else:
        lines += [f"DTSTART:{_utc(s)}", f"DTEND:{_utc(t)}"]
    lines += [f"SUMMARY:{_esc(e['title'])}", f"DESCRIPTION:{_esc(e['description'])}"]
    if e["location"]:
        lines.append(f"LOCATION:{_esc(e['location'])}")
    for r in e["reminders"]:
        lines += ["BEGIN:VALARM", "ACTION:DISPLAY", f"DESCRIPTION:{_esc(r['text'])}",
                  f"TRIGGER:{_trigger(datetime.fromisoformat(r['at'][:19]), s)}", "END:VALARM"]
    lines += ["END:VEVENT", "END:VCALENDAR"]
    return "\r\n".join(_fold(l) for l in lines) + "\r\n"


def bundle(view: dict, tone_key: str = "basic") -> dict:
    """entry + 구글 주소 + 캘린더 파일 글."""
    e = entry(view, tone_key)
    return e | {"google_url": google_url(e), "ics": to_ics(e, f"gabangssok-{view['id']}-{view['date']}-{e['tone']}@gabangssok"),
                "filename": f"gabangssok-{view['date']}.ics"}

app/chaeng/guard.py:
"""알림장 글에서 금지·조건을 놓치지 않게 뽑는 규칙(모델 호출 없음, 표준 라이브러리만).

- 금지: "유리병·탄산음료와 장난감은 가져오지 않습니다", "( 장난감 등 불가 )", "탄산음료 X"
- 조건: "마실 물(플라스틱 물통)" → 조건 '플라스틱 물통'
- 열린 목록: 준비물 줄이 "… 등"으로 끝남 → 추천으로 채울 자리
- 사람·상황에 따라 다른 것: "필요한 학생", "우천 시"
- 원문 근거: 항목이 나온 줄을 그대로 붙인다(알림장 전문은 저장하지 않고 그 줄만)

여기서 뽑은 것은 판정이 아니라 표시다. 아이·보호자가 화면에서 보고 직접 확인한다.
"""
from __future__ import annotations

import re

_PAREN = re.compile(r"^(.*?)\s*[(（](.+?)[)）]\s*(.*)$")
_QTY = re.compile(r"(\d+|한|두|세)\s*(개|장|자루|권|벌|켤레|병|봉지|통|쪽)")
_SPLIT_NAMES = re.compile(r"\s*(?:[·,、/]|와\s|과\s|및\s|이나\s|\s또는\s|\s혹은\s|\s등의?\s)\s*")   # "핸드폰 등 귀중품" → 핸드폰, 귀중품
_BAN_VERB = re.compile(
    r"([^.!?()（）\n]{1,60}?)\s*(?:은|는|을|를|도)?\s*"
    r"(?:가져오지|가져가지|가지고\s?오지|가지고\s?가지|갖고\s?오지|지참하지|싸\s?오지|들고\s?오지|휴대하지|소지하지"
    r"|(?:가지고|갖고)\s?등교하지|착용하지)\s*(?:않|말|마|못)(?!아도|어도)")
_BAN_MARK = re.compile(
    r"([가-힣A-Za-z0-9 ·,、/]{1,40}?)\s*(?:등)?\s*(?:은|는|의)?\s*"
    r"(?:(?:지참|반입|사용|휴대|소지|착용)\s*(?:은|는|이|을|를)?\s*)?(불가|금지|안\s?됩니다|안\s?돼요|안\s?됨|[X✕×])(?:합니다|입니다|됩니다|해요|예요)?(?![가-힣A-Za-z])")
_BAN_HEAD = re.compile(                              # "(※ 입장제한: 래쉬가드, 수경)", "※ 휴대지참 금지 품목: 게임기, 폭죽 등"
    r"(?:입장\s?제한|(?:휴대\s?)?(?:지참\s?)?(?:반입\s?)?금지\s?(?:품목|물품|물건)?|가져오지\s?않는\s?것)\s*[:：]\s*(.+)$")
_BAN_IF = re.compile(                                # "장난감을 가져오면 안 됩니다"
    r"([^.!?()（）\n]{1,60}?)\s*(?:은|는|을|를|도)?\s*"
    r"(?:가져오면|가져오시면|가지고\s?오면|갖고\s?오면|지참하면|들고\s?오면|넣어\s?오면|휴대하면|소지하면)\s*안\s?(?:됩니다|돼요|돼|됨|되어요|된다|되요)")
_NOT_NEEDED = re.compile(r"([가-힣A-Za-z0-9 ·,]{1,30}?)\s*(?:은|는)\s*(?:필요\s?없|준비하지\s?않아도|가져오지\s?않아도)")
_NEEDED_ONLY = re.compile(r"필요한\s*(?:학생|사람|어린이|친구)|해당\s*(?:학생|자)|희망자|복용\s*중")
_RAIN_ONLY = re.compile(r"우천\s?시|비\s?(?:가)?\s?(?:오면|올\s?경우|올\s?때)")
_WEAR = re.compile(r"복장|옷차림|입고|착용|신고|체육복|활동복|운동화|긴바지|긴팔|반티|단체복")
_SUBMIT = re.compile(r"회신서|신청서|동의서|참가서|확인서|회신")
_CONSUMED = re.compile(r"간식|과자|음료|물티슈|휴지|티슈|비닐|봉지|봉투|약$|멀미약|밴드|도시락$|김밥|과일|회신서|신청서|동의서")
_KEEP = re.compile(r"도시락\s?통|물통|텀블러|수저|젓가락")
_TRIM = re.compile(r"^[\s※\-•·*\d.)◦○■□▶★]+|[\s.,·]+$")
_ADVICE = re.compile(r"(?:자제|지양|권장|삼가)$")             # "이동차량 내 취식 자제"는 물건이 아니라 행동 권고
_ACTION_BAN = re.compile(r"(?:^|\s)(?:세탁|환불|교환|반품|주차|출입|입장|변경|취소|대여|재사용|수선)$")   # "속옷(여벌, 세탁 불가)": 세탁할 수 없다는 설명
_STOP = {"", "등", "것", "물건", "물품", "기타", "그 외", "준비물"}
_ONE = {"캔", "껌", "칼", "돈", "물", "빵", "떡", "총", "공", "술", "약"}      # 한 글자여도 물건인 것

# 금지된 것이 어떤 준비물의 '안 되는 대체물'인지(같은 자리에 놓일 수 있는 것)
_SUBSTITUTE_OF = [
    (re.compile(r"유리병|유리\s?용기|캔"), re.compile(r"^(?:마실\s?)?물$|음료|물통|텀블러|생수")),
    (re.compile(r"탄산|콜라|사이다"), re.compile(r"^(?:마실\s?)?물$|음료|생수")),
    (re.compile(r"일회용"), re.compile(r"도시락|수저|물통")),
    (re.compile(r"슬리퍼|샌들|크록스"), re.compile(r"운동화|신발")),
]


def _clean(name: str) -> str:
    name = _TRIM.sub("", name)
    name = re.sub(r"\s*(?:등|같은\s?것)$", "", name).strip()
    return re.sub(r"\s+", " ", name)


def _names(chunk: str) -> list[str]:
    out = []
    for part in _SPLIT_NAMES.split(chunk):
        n = _clean(part)
        n = re.sub(r"^(?:그리고|또한|단|특히)\s*", "", n)
        n = re.sub(r"(?:은|는)?\s+[가-힣]+(?:으로|에)$", "", n)  # "개인 귀중품은 수영장으로" → "개인 귀중품"
        n = re.sub(r"^[가-힣]+\s내\s+", "", n)                # "체험시설 내 외부 음식" → "외부 음식"
        n = re.sub(r"(?<=[가-힣])(?:을|를)$", "", n)          # "장난감을" → "장난감"
        n = re.sub(r"(?<=[가-힣]{2})(?:은|는)$", "", n)
        if _ADVICE.search(n):
            continue
        if n not in _STOP and (1 < len(n) <= 16 or n in _ONE) and not re.search(r"습니다|세요|니다$|가져오|가지고|갖고|지참하|들고", n):
            out.append(n)
    return out


def lines_of(text: str) -> list[str]:
    out = []
    for raw in (text or "").replace("\r", "").split("\n"):
        for s in re.split(r"(?<=[.!?。])\s+|\s*※\s*", raw):
            s = s.strip()
            if s:
                out.append(s)
    return out


def split_name(name: str) -> tuple[str, str]:
    """'마실 물(플라스틱 물통)' → ('마실 물', '플라스틱 물통')"""
    name = name.strip()
    start = min((i for i in (name.find("("), name.find("（")) if i >= 0), default=-1)
    if start < 0:
        return name, ""
    depth = 0
    for i in range(start, len(name)):                 # 겹친 괄호: 바깥 괄호의 짝을 찾는다
        if name[i] in "(（":
            depth += 1
        elif name[i] in ")）":
            depth -= 1
            if depth == 0:
                return (name[:start] + " " + name[i + 1:]).strip(), name[start + 1:i].strip()
    return name[:start].strip(), name[start + 1:].strip()


def find_forbidden(text: str) -> list[dict]:
    """알림장 글에서 가져오면 안 되는 것. [{name, evidence}] (같은 이름은 한 번만)"""
    seen, out = set(), []
    for line in lines_of(text):
        heads = [m.group(1) for m in _BAN_HEAD.finditer(line)]
        line_wo = _BAN_HEAD.sub(" ", line)                 # 머리말 뒤 목록은 통째로 읽고, 아래 규칙이 다시 읽지 않게 뺀다
        chunks = [m.group(1) for m in _BAN_IF.finditer(line_wo)]
        rest = _BAN_IF.sub(" ", line_wo)                   # 위에서 읽은 토막은 아래 규칙이 다시 읽지 않게 뺀다
        chunks += [m.group(1) for m in _BAN_VERB.finditer(rest)]
        chunks += [m.group(1) for m in _BAN_MARK.finditer(rest) if not _ACTION_BAN.search(m.group(1).strip())]
        chunks = [re.split(r"위해서?|위하여|때문에|인해|(?:문제|이유)로", c)[-1] for c in chunks]      # "식중독 예방을 위해 외부음식 반입은 금지" → "외부음식"
        chunks = [c.split(":")[-1].split("：")[-1] for c in chunks]
        for h in heads:                                    # 목록 안의 괄호 설명은 떼고 이름만 읽는다
            chunks += [re.sub(r"[(（][^)）]*[)）]?", "", x).strip(" )）") for x in re.split(r"[,、]", h)]
        for chunk in chunks:
            for n in _names(chunk):
                if n not in seen:
                    seen.add(n)
                    out.append({"name": n, "evidence": line[:140]})
    return out


def find_not_needed(text: str) -> list[dict]:
    seen, out = set(), []
    for line in lines_of(text):
        for m in _NOT_NEEDED.finditer(line):
            for n in _names(m.group(1)):
                if n not in seen:
                    seen.add(n)
                    out.append({"name": n, "evidence": line[:140]})
    return out


def list_open(text: str) -> bool:
    """준비물 줄이 '등'으로 끝나는가(목록에 없는 것이 더 있을 수 있음)."""
    for line in lines_of(text):
        if re.search(r"준비물|챙길\s?것|지참물", line) and re.search(r"(?:^|[\s,、])등\s*(?:[.)]?\s*$|[(（*])", line):
            return True
    return False


def _segments(text: str, base: str) -> list[str]:
    """통신문에서 이 물건을 말하는 토막만(쉼표·마침표로 끊은 조각). 같은 줄의 다른 물건 조건은 끌어오지 않는다."""
    key = re.sub(r"\s+", "", base)
    if not text or len(key) < 2:
        return []
    out = []
    for line in lines_of(text):
        if re.search(r"준비물|챙길\s?것|지참물", line):
            continue                                   # 준비물 나열 줄은 항목 이름으로 이미 읽었다
        for seg in re.split(r"[,、!?]|\.\s", line):
            if key in re.sub(r"\s+", "", seg):
                out.append(seg.strip())
    return out


def annotate(name: str, text: str = "", forbidden: list[dict] | None = None) -> dict:
    """준비물 이름 하나에 조건·수량·종류·근거를 붙인다."""
    base, paren = split_name(name)
    meta: dict = {"base": base, "kind": "carry"}
    whole = name
    if paren:
        if _BAN_MARK.search(paren) or _BAN_VERB.search(paren):
            pass                                   # 괄호 안이 금지 문구면 조건으로 쓰지 않는다(금지 목록으로 간다)
        elif paren.strip() in ("선택", "선택 사항", "희망"):
            meta["optional_by_notice"] = True      # 알림장이 선택이라고 적은 것만 선택. 안 적혀 있으면 전부 챙길 것
        elif _NEEDED_ONLY.search(paren):
            meta["conditional"] = "needed"
        elif _RAIN_ONLY.search(paren):
            meta["conditional"] = "rain"
        else:
            meta["condition"] = paren
    if "conditional" not in meta:
        if _NEEDED_ONLY.search(whole) or re.search(r"개인\s?약|상비약", whole):
            meta["conditional"] = "needed"
        elif _RAIN_ONLY.search(whole):
            meta["conditional"] = "rain"
            base = _RAIN_ONLY.sub("", base).strip() or base
            meta["base"] = base
    q = _QTY.search(whole)
    if q:
        meta["quantity"] = q.group(0)
        rest = re.sub(r"\s+", " ", base.replace(q.group(0), "")).strip()
        if rest:
            meta["base"] = base = rest
    for seg in _segments(text, base):                  # 항목 이름에는 없고 통신문 글에만 있는 제한
        if "conditional" not in meta and _NEEDED_ONLY.search(seg):
            meta["conditional"] = "needed"
        if "conditional" not in meta and _RAIN_ONLY.search(seg):
            meta["conditional"] = "rain"
        qs = _QTY.search(seg)
        if qs and "quantity" not in meta:
            meta["quantity"] = qs.group(0) + ("만" if re.search(re.escape(qs.group(0)) + r"\s*만", seg) else "")
    alts = [a.strip() for a in re.split(r"\s(?:또는|혹은|or)\s", base) if a.strip()]
    if len(alts) > 1:
        meta["any_of"] = alts
    if _SUBMIT.search(base):
        meta["kind"] = "submit"
    elif _WEAR.search(whole) and not re.search(r"실내화|여벌|갈아입", whole):
        meta["kind"] = "wear"
    meta["bring_back"] = bool(_KEEP.search(base)) or not _CONSUMED.search(base)
    if meta["kind"] == "submit":
        meta["bring_back"] = False
    na = [f["name"] for f in (forbidden or [])
          if any(a.search(f["name"]) and b.search(base) for a, b in _SUBSTITUTE_OF)]
    if na:
        meta["not_accepted"] = na
    if text:
        key = re.sub(r"\s+", "", base)[:6]
        for line in lines_of(text):
            if key and key in re.sub(r"\s+", "", line):
                meta["evidence"] = line[:140]
                break
    return meta


def analyze(text: str, item_names: list[str]) -> dict:
    """알림장 글 + 뽑힌 준비물 이름 → 금지 목록, 열린 목록 여부, 항목별 표시."""
    forb = find_forbidden(text)
    for n in item_names:                       # 항목 괄호 안에 숨은 금지: "비닐 봉투 ( 장난감 등 불가 )"
        _, paren = split_name(n)
        if paren and (_BAN_MARK.search(paren) or _BAN_VERB.search(paren)):
            for f in find_forbidden(paren):
                if f["name"] not in {x["name"] for x in forb}:
                    forb.append({"name": f["name"], "evidence": n[:140]})
    return {
        "forbidden": forb,
        "not_needed": find_not_needed(text),
        "list_open": list_open(text) or any(re.search(r"등\s*$", n) for n in item_names[-1:]),
        "items": {n: annotate(n, text, forb) for n in item_names},
    }

app/chaeng/recommend.py:
"""준비물 추천(모델 호출 없음). 알림장 목록이 '등'으로 끝나거나 평소 일정일 때 빈자리를 채운다.

추천은 네 갈래이고 모두 '추천'이라고 표시한다(알림장에 적힌 것과 섞지 않는다).
1. 상황: 일정 제목으로 상황(현장체험학습, 생존수영 …)을 찾아 그 상황의 기본 준비물
2. 날씨·활동: 비·미세먼지·더위·추위·물에 젖는 활동·버스 이동
3. 아이: 보호자가 고른 특성(멀미, 안경 …). 약처럼 보호자가 정할 것은 보호자 화면에만 보인다
4. 꼬리표: 집에서 '항상 챙기는 것'으로 정해 둔 물건(지갑, 교통카드 …)
이미 목록에 있는 것(같은 뜻의 다른 이름 포함)은 추천하지 않는다.
"""
from __future__ import annotations

import json
import os
import re

DATA_PATH = os.path.join(os.path.dirname(__file__), "scenarios.json")
_GRADE_RANK = {"좋음": 0, "보통": 1, "나쁨": 2, "매우나쁨": 3}
_SYNONYMS = [                      # 같은 물건으로 치는 이름(꾸밈말·수량·괄호를 뗀 낱말 기준)
    {"물", "마실물", "물통", "물병", "음료", "음료수", "생수", "텀블러", "물하나더"},
    {"우산", "우비", "우의", "비옷", "접이식우산"},
    {"돗자리", "매트"},
    {"물티슈", "휴지", "티슈"},
    {"필기도구", "필기구", "연필", "필통", "펜"},
    {"간식", "과자", "간식조금"},
    {"마스크", "kf80마스크", "kf94마스크"},
    {"겉옷", "외투", "점퍼", "바람막이", "보온용점퍼"},
    {"여벌옷", "갈아입을옷", "여벌티셔츠", "여분옷"},
    {"수건", "손수건", "타월"},
    {"선크림", "썬크림", "자외선차단제"},
    {"비닐봉지", "비닐봉투", "비닐", "위생봉지", "지퍼백", "젖은것담을봉지"},
    {"양말", "여벌양말", "두꺼운양말"},
    {"운동화", "신발"},
    {"체육복", "옷", "활동복", "복장", "운동복장"},
    {"물안경", "수경"},
    {"세면도구", "샤워"},
]
_MODIFIER = re.compile(r"^(개인용|개인|휴대용|작은|얇은|따뜻한|편한|간편한|여분의)")
_COUNT = re.compile(r"(\d+|한|두|세)\s*(개|장|자루|권|벌|켤레|병|봉지|통|쪽)(\s*(이상|만))?")
LIMITS = {"scenario": 5, "wear": 2, "weather": 4, "personal": 3}
_MEDICINE = re.compile(r"상비약|비상약|멀미약|알레르기 약|개인\s?약|약품|기피제|(?<!치)약$")


def is_medicine(name: str) -> bool:
    """약은 아이가 아니라 보호자가 정한다."""
    return bool(_MEDICINE.search(re.sub(r"[(（].*?[)）]", "", name or "").strip()))


def load(path: str | None = None) -> dict:
    with open(path or DATA_PATH, encoding="utf-8") as f:
        return json.load(f)


def tokens(name: str) -> set[str]:
    """이름을 견줄 낱말로 나눈다: 괄호·수량·'우천 시'·꾸밈말을 떼고 '·', '또는'으로 가른다."""
    name = re.sub(r"[(（].*?[)）]", " ", name or "")
    name = re.sub(r"우천\s?시|비\s?올\s?때", " ", name)
    name = _COUNT.sub(" ", name)
    out = set()
    for part in re.split(r"[·,/]|\s또는\s|\s혹은\s", name):
        tok = re.sub(r"[\s\-]+", "", part).lower()
        tok = _MODIFIER.sub("", tok) or tok
        if tok:
            out.add(tok)
    return out


def same(a: str, b: str) -> bool:
    """같은 물건으로 볼 수 있는가: 낱말이 같거나 같은 뜻 묶음에 있을 때만. 한쪽이 다른 쪽을 품는 것(안경과 안경집)은 다른 물건이다."""
    for x in tokens(a):
        for y in tokens(b):
            if x == y or any(x in g and y in g for g in _SYNONYMS):
                return True
    return False


def match_scenario(event: dict, data: dict) -> dict | None:
    """일정 제목·메모·장소에서 가장 많이 맞는 상황. 없으면 None."""
    hay = " | ".join(str(event.get(k) or "") for k in ("title", "location", "source_title"))   # 칸을 이어 붙여 생기는 가짜 낱말을 막는다
    best, score, fallback = None, 0, None
    for sc in data["scenarios"]:
        hits = sum(len(k) for k in sc.get("match", []) if k in hay)
        if not hits:
            continue
        if sc.get("fallback"):                       # 넓은 이름(현장체험학습)은 더 좁은 상황이 없을 때만
            fallback = fallback or sc
        elif hits > score:
            best, score = sc, hits
    return best or fallback


def flags(event: dict, scenario: dict | None) -> set[str]:
    """날씨와 활동에서 조건 꼬리표를 만든다."""
    out: set[str] = set(scenario.get("tags", []) if scenario else [])
    if event.get("outdoor"):
        out.add("outdoor")
    hay = " ".join(str(event.get(k) or "") for k in ("title", "notes", "location"))
    if re.search(r"버스|전세|차량 ?이동", hay):
        out.add("bus")
    if re.search(r"물놀이|수영|하천|갯벌|계곡|물총", hay):
        out.add("wet_activity")
    w = event.get("weather") or {}
    if w.get("status") == "ok":
        prob = w.get("rain_prob_window") if w.get("rain_prob_window") is not None else w.get("rain_prob")
        if (prob is not None and prob >= 30) or (w.get("rain_mm") or 0) >= 1 or w.get("rain_signal") in ("rain", "maybe"):
            out.add("rain")
        worst = max([_GRADE_RANK.get(g, 0) for g in (w.get("pm10_grade"), w.get("pm25_grade")) if g] or [0])
        if worst >= 2:
            out.add("dust_bad")
        if w.get("t_max") is not None and w["t_max"] >= 28:
            out.add("hot")
        if w.get("t_min") is not None and w["t_min"] <= 5:
            out.add("cold")
    return out


def _basis(item: dict) -> str:
    n = len(item.get("seen_in") or [])
    return f"비슷한 알림장 {n}건에서 봤어요" if n else "가방쏙 제안"


def _rec(item: dict, group: str) -> dict:
    return {
        "name": item["name"], "emoji": item.get("emoji", "🎒"), "kind": item.get("kind", "carry"),
        "why": re.sub(r"\s*\[제안\]\s*$", "", item.get("why", "")), "group": group, "basis": _basis(item),
        "guardian_decides": bool(item.get("guardian_decides")) or is_medicine(item["name"]),   # 약은 보호자가 정한다
    }


def recommend(event: dict, profile: dict | None = None, forgot: dict | None = None,
              declined: list[str] | None = None, data: dict | None = None,
              exclude: list[str] | None = None) -> dict:
    """일정 하나에 대한 추천.

    event: {title, notes, location, outdoor, weather, items:[{name, source}]}
    profile: {traits:[...], always:[...]}   forgot: {물건 이름: 깜빡한 횟수}
    돌려주는 것: {scenario, flags, recs:[...], watch:[...]}
    """
    data = data or load()
    profile = profile or {}
    have = [i["name"] for i in event.get("items", [])]
    skip = list(have) + list(declined or []) + list(exclude or [])   # exclude: 알림장이 가져오지 말라고 한 것
    scenario = match_scenario(event, data)
    fl = flags(event, scenario)
    recs: list[dict] = []

    def add(item: dict, group: str) -> bool:
        if any(same(item["name"], s) for s in skip):
            return False
        recs.append(_rec(item, group))
        skip.append(item["name"])
        return True

    for name in profile.get("always") or []:               # 꼬리표: 항상 챙기는 것
        if add({"name": name, "emoji": "🏷️", "why": "항상 챙기기로 한 물건이에요", "seen_in": []}, "tag"):
            recs[-1]["basis"] = "우리 집 꼬리표"

    if scenario:
        n = 0
        for it in scenario.get("defaults", []):
            if "cold" in fl and re.search(r"선크림|부채|얼음", it["name"]):
                continue
            if n < LIMITS["scenario"] and add(it, "scenario"):
                n += 1
        n = 0
        for it in scenario.get("wear", []):
            if "cold" in fl and re.search(r"샌들|반팔|반바지|수영복", it["name"]):
                continue                                   # 추운 날에는 여름 차림을 권하지 않는다
            if "샌들" in it["name"] and not re.search(r"갯벌|하천|바다|해변|계곡|물놀이", " ".join(str(event.get(k) or "") for k in ("title", "location", "notes"))):
                continue                                   # 물에 들어가는 신발은 그런 곳에 갈 때만
            if n < LIMITS["wear"] and add(it | {"kind": "wear"}, "scenario"):
                n += 1

    n = 0
    for it in data.get("conditional", []):
        if it["when"] not in fl:
            continue
        if it.get("needs_tag") and it["needs_tag"] not in fl:
            continue
        if it.get("needs_trait") and it["needs_trait"] not in (profile.get("traits") or []):
            continue
        if n < LIMITS["weather"] and add(it, "weather"):
            n += 1

    n = 0
    for p in data.get("personal", []):
        if p["trait"] not in (profile.get("traits") or []):
            continue
        for it in p.get("add", []):
            if it.get("needs_tag") and it["needs_tag"] not in fl:
                continue
            if n < LIMITS["personal"] and add(it, "personal"):
                recs[-1]["why"] = recs[-1]["why"] or p.get("label", "")
                n += 1

    watch = [h for h in have if any(same(h, k) and c >= 1 for k, c in (forgot or {}).items())]
    return {
        "scenario": {"id": scenario["id"], "name": scenario["name"]} if scenario else None,
        "flags": sorted(fl),
        "often_forbidden": [f["name"] for f in (scenario or {}).get("often_forbidden", [])],
        "recs": recs,
        "watch": watch,
    }


def starter_items(scenario_id: str, data: dict | None = None) -> list[dict]:
    """알림장 없는 평소 일정을 만들 때의 기본 준비물(전부 '추천' 출처)."""
    data = data or load()
    sc = next((s for s in data["scenarios"] if s["id"] == scenario_id), None)
    if not sc:
        return []
    return [_rec(it, "scenario") for it in sc.get("defaults", [])] + [_rec(it | {"kind": "wear"}, "scenario") for it in sc.get("wear", [])]

app/chaeng/service.py:
"""챙겼지 추가 기능의 저장과 계산. 웹 서버 종류와 상관없이 쓴다(FastAPI 라우터, 예시 서버 둘 다 여기를 부른다).

같은 SQLite 파일에 표 네 개를 더한다. 알림장 전문과 사진은 저장하지 않는다(항목이 나온 줄만 근거로 남긴다).
"""
from __future__ import annotations

import json
from datetime import datetime

from .. import db
from . import calendar_out, guard, recommend, tone

SCHEMA = """
CREATE TABLE IF NOT EXISTS plus_item (item_id INTEGER PRIMARY KEY, meta TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plus_event (event_id INTEGER PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plus_sticker (
  id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL, sticker TEXT NOT NULL,
  message TEXT, giver TEXT NOT NULL DEFAULT '엄마', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plus_kv (key TEXT PRIMARY KEY, value TEXT NOT NULL);
"""
OPTIONAL_SOURCES = ("ai", "weather")          # 자동으로 붙은 추천. 안 넣어도 '다 챙겼지'를 막지 않는다
STICKERS = ["⭐", "👍", "💪", "🌈", "🏅", "💜"]
TRAITS = [(p["trait"], p["label"]) for p in recommend.load().get("personal", [])]
DEFAULT_PROFILE = {"name": "", "grade": None, "traits": [], "always": [], "tone": "basic"}


def now() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def init():
    with db.tx() as con:
        con.executescript(SCHEMA)
    sweep()


# ---------- 작은 저장소 ----------
def _kv_get(key: str, default):
    with db.tx() as con:
        row = con.execute("SELECT value FROM plus_kv WHERE key=?", (key,)).fetchone()
    return json.loads(row["value"]) if row else default


def _kv_set(key: str, value):
    with db.tx() as con:
        con.execute("INSERT INTO plus_kv(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                    (key, json.dumps(value, ensure_ascii=False)))


def get_profile() -> dict:
    return DEFAULT_PROFILE | _kv_get("profile", {})


def set_profile(body: dict) -> dict:
    known = {t for t, _ in TRAITS}
    p = get_profile()
    if "name" in body:
        p["name"] = str(body["name"] or "")[:12]
    if "grade" in body:
        p["grade"] = int(body["grade"]) if str(body["grade"] or "").isdigit() else None
    if "traits" in body:
        p["traits"] = [t for t in (body["traits"] or []) if t in known]
    if "always" in body:
        p["always"] = [str(x).strip()[:12] for x in (body["always"] or []) if str(x).strip()][:6]
    if "tone" in body and body["tone"] in tone.TONES:
        p["tone"] = body["tone"]
    _kv_set("profile", p)
    return p


def _event_data(eid: int) -> dict:
    with db.tx() as con:
        row = con.execute("SELECT data FROM plus_event WHERE event_id=?", (eid,)).fetchone()
    base = {"forbidden": [], "not_needed": [], "list_open": False, "declined": [], "flagged": [], "removed": [],
            "returned": [], "analyzed": False}
    return base | (json.loads(row["data"]) if row else {})


def _event_save(eid: int, data: dict):
    with db.tx() as con:
        con.execute("INSERT INTO plus_event(event_id,data) VALUES(?,?) ON CONFLICT(event_id) DO UPDATE SET data=excluded.data",
                    (eid, json.dumps(data, ensure_ascii=False)))


def _meta_all(item_ids: list[int]) -> dict[int, dict]:
    if not item_ids:
        return {}
    with db.tx() as con:
        rows = con.execute(f"SELECT item_id, meta FROM plus_item WHERE item_id IN ({','.join('?' * len(item_ids))})",
                           item_ids).fetchall()
    return {r["item_id"]: json.loads(r["meta"]) for r in rows}


def _meta_save(item_id: int, meta: dict):
    with db.tx() as con:
        con.execute("INSERT INTO plus_item(item_id,meta) VALUES(?,?) ON CONFLICT(item_id) DO UPDATE SET meta=excluded.meta",
                    (item_id, json.dumps(meta, ensure_ascii=False)))


# ---------- 알림장 분석 ----------
def analyze(eid: int, text: str) -> dict | None:
    """알림장 글에서 금지·조건·근거를 뽑아 일정에 붙인다. 글 자체는 저장하지 않는다."""
    ev = db.get_event(eid)
    if not ev:
        return None
    notice_items = [i for i in ev["items"] if i["source"] in ("notice", "user")]
    res = guard.analyze(text or "", [i["name"] for i in notice_items])
    for it in notice_items:
        _meta_save(it["id"], res["items"][it["name"]])
    data = _event_data(eid)
    data |= {"forbidden": res["forbidden"], "not_needed": res["not_needed"], "list_open": res["list_open"],
             "analyzed": bool((text or "").strip())}       # 글 없이 부르면 '아직 확인 못 함'으로 남는다
    _event_save(eid, data)
    return view(eid)


# ---------- 화면에 주는 묶음 ----------
def view(eid: int) -> dict | None:
    """일정 + 항목별 표시 + 금지 + 추천 + 스티커 + 집계."""
    ev = db.get_event(eid)
    if not ev:
        return None
    data = _event_data(eid)
    metas = _meta_all([i["id"] for i in ev["items"]])
    banned = [f["name"] for f in data["forbidden"] + data["not_needed"]]
    rec = recommend.recommend(ev, get_profile(), _kv_get("forgot", {}), data["declined"], exclude=banned)
    for it in ev["items"]:
        m = metas.get(it["id"])
        if m is None:                                    # 분석 전이거나 나중에 더한 항목: 이름만으로 표시를 만든다
            m = guard.annotate(it["name"], "", data["forbidden"])
        it["meta"] = m
        it["optional"] = it["source"] in OPTIONAL_SOURCES or bool(m.get("optional_by_notice"))
        it["guardian"] = it["blocked"] = False
        if m.get("guardian") or m.get("conditional") == "needed" or recommend.is_medicine(it["name"]):
            it["optional"] = it["guardian"] = True       # 약과 "필요한 학생만": 보호자가 정한다. 아이 미션에는 넣지 않는다
        elif m.get("conditional") == "rain":             # "우천 시": 비 소식이 있을 때만 세는 준비물
            it["optional"] = "rain" not in rec["flags"]
        if any(recommend.same(it["name"], n) for n in banned):
            if it["source"] in ("ai", "weather", "recommend"):
                it["blocked"] = it["optional"] = True    # 자동 추천이 통신문의 금지와 겹치면 아이에게 보이지 않는다
            else:
                it["conflict"] = True                    # 통신문 준비물이 금지와 겹치면 지우지 않고 보호자에게 알린다
        it["skipped"] = it["id"] in data.get("skipped", [])
        if it["skipped"]:                                # 보호자가 '이번엔 빼기'로 둔 것: 지우지 않고, 세지 않고, 아이 미션에 넣지 않는다
            it["optional"] = True
    alerts = [f | {"flagged": f["name"] in data["flagged"], "removed": f["name"] in data["removed"]} for f in data["forbidden"]]
    ev["plus"] = {
        "analyzed": data["analyzed"], "list_open": data["list_open"], "forbidden": alerts,
        "not_needed": data["not_needed"], "scenario": rec["scenario"], "flags": rec["flags"],
        "often_forbidden": rec["often_forbidden"] if not alerts else [],
        "recs": [r for r in rec["recs"] if not r["guardian_decides"]],
        "guardian_recs": [r for r in rec["recs"] if r["guardian_decides"]],
        "watch": rec["watch"], "stickers": stickers(eid), "returned": data["returned"],
        "summary": summarize(ev, data),
    }
    return ev


def summarize(ev: dict, data: dict) -> dict:
    """세는 항목(알림장·직접·받아들인 추천)과 선택·자동 추천을 나눠 센다. view() 가 optional 을 붙인 뒤에 부른다."""
    req = [i for i in ev["items"] if not i.get("optional")]
    opt = [i for i in ev["items"] if i.get("optional") and not i.get("blocked") and not i.get("guardian") and not i.get("skipped")]
    left = [i["name"] for i in req if not i["checked"]]
    open_alerts = [n for n in data["flagged"] if n not in data["removed"]]      # 사진에 보였는데 아직 안 뺀 것만 막는다
    return {
        "counted": len(req), "packed": len(req) - len(left), "left": left,
        "optional": len(opt), "optional_packed": sum(1 for i in opt if i["checked"]),
        "optional_left": [i["name"] for i in opt if not i["checked"]],
        "open_alerts": open_alerts, "list_open": data["list_open"],
        "skipped": [i["name"] for i in ev["items"] if i.get("skipped")],
        "all_packed": bool(req) and not left,
        "can_finish": bool(req) and not left and not open_alerts,     # '다 챙겼지'를 말해도 되는가
    }


# ---------- 추천 받아들이기 ----------
def accept_rec(eid: int, name: str) -> dict | None:
    v = view(eid)
    if not v:
        return None
    rec = next((r for r in v["plus"]["recs"] + v["plus"]["guardian_recs"] if r["name"] == name), None)
    if rec:
        iid = db.add_item(eid, rec["name"], source="recommend", reason=f"{rec['why']} · {rec['basis']}")
        _meta_save(iid, guard.annotate(rec["name"]) | {"kind": rec["kind"], "emoji": rec["emoji"], "group": rec["group"],
                                                       "guardian": rec["guardian_decides"]})
    return view(eid)


def decline_rec(eid: int, name: str) -> dict | None:
    data = _event_data(eid)
    if name not in data["declined"]:
        data["declined"].append(name)
        _event_save(eid, data)
    return view(eid)


def flag_forbidden(eid: int, names: list[str]):
    """사진에서 가져오면 안 되는 것이 보였다고 적어 둔다(아이가 '뺐어'를 누를 때까지 결과에 남는다)."""
    if not names:
        return
    data = _event_data(eid)
    data["flagged"] = list(dict.fromkeys(data["flagged"] + list(names)))
    data["removed"] = [n for n in data["removed"] if n not in names]
    _event_save(eid, data)


def alert_removed(eid: int, name: str, removed: bool = True) -> dict | None:
    data = _event_data(eid)
    data["removed"] = [n for n in data["removed"] if n != name] + ([name] if removed else [])
    _event_save(eid, data)
    return view(eid)


def scenario_list() -> list[dict]:
    return [{"id": s["id"], "name": s["name"], "type": s["type"]} for s in recommend.load()["scenarios"]]


def quick_event(scenario_id: str, date: str, title: str | None = None) -> int | None:
    """알림장 없는 평소 일정: 상황을 고르면 기본 준비물이 '추천' 출처로 들어간다."""
    data = recommend.load()
    sc = next((s for s in data["scenarios"] if s["id"] == scenario_id), None)
    if not sc:
        return None
    date = datetime.strptime(str(date), "%Y-%m-%d").date().isoformat()   # 틀린 날짜는 여기서 멈추고, 저장은 늘 YYYY-MM-DD
    recs = [r for r in recommend.starter_items(scenario_id, data) if not r["guardian_decides"]]
    eid = db.insert_event(
        {"title": title or sc["name"], "kind": "event", "date": date, "outdoor": "outdoor" in sc.get("tags", []),
         "notes": "알림장 없이 만든 일정이에요. 준비물은 가방쏙 추천이라 빼거나 더해도 돼요."},
        [{"name": r["name"], "source": "recommend", "reason": f"{r['why']} · {r['basis']}"} for r in recs])
    ev = db.get_event(eid)
    for it, r in zip(ev["items"], recs):
        _meta_save(it["id"], guard.annotate(it["name"]) | {"kind": r["kind"], "emoji": r["emoji"], "group": "scenario"})
    _event_save(eid, _event_data(eid) | {"analyzed": True})
    return eid


# ---------- 아이 결과 보고 ----------
def kid_report(eid: int) -> dict | None:
    """아이가 '엄마에게 보여 주기'를 누르면 보호자 화면 알림함에 결과를 남긴다(실제 푸시가 아니다)."""
    v = view(eid)
    if not v:
        return None
    s = v["plus"]["summary"]
    forgot, data = _kv_get("forgot", {}), _event_data(eid)
    for key in data.get("forgot_logged", []):            # 같은 일정을 다시 보내도 한 번만 센다
        forgot[key] = max(0, forgot.get(key, 0) - 1)
    logged = [guard.split_name(name)[0] for name in s["left"]]
    for key in logged:
        forgot[key] = forgot.get(key, 0) + 1
    _kv_set("forgot", {k: v for k, v in forgot.items() if v > 0})
    _event_save(eid, data | {"forgot_logged": logged})
    title, body = tone.kid_report(v, s, get_profile())
    with db.tx() as con:
        con.execute("DELETE FROM notifications WHERE event_id=? AND kind='kid'", (eid,))
        con.execute("INSERT INTO notifications(event_id,kind,fire_at,message) VALUES(?, 'kid', ?, ?)",
                    (eid, now(), f"{title}\n{body}"))
    return {"title": title, "body": body, "summary": s}


# ---------- 칭찬 스티커 ----------
def stickers(eid: int | None = None) -> list[dict]:
    q, args = "SELECT s.*, e.title AS event_title, e.date AS event_date FROM plus_sticker s JOIN events e ON e.id=s.event_id", []
    if eid is not None:
        q += " WHERE s.event_id=?"
        args.append(eid)
    with db.tx() as con:
        return [dict(r) for r in con.execute(q + " ORDER BY s.id DESC LIMIT 60", args)]


def give_sticker(eid: int, sticker: str, message: str = "", giver: str = "엄마") -> dict | None:
    if not db.get_event(eid) or sticker not in STICKERS:
        return None
    with db.tx() as con:
        con.execute("INSERT INTO plus_sticker(event_id,sticker,message,giver,created_at) VALUES(?,?,?,?,?)",
                    (eid, sticker, (message or "")[:40], (giver or "엄마")[:6], now()))
    return {"stickers": stickers(eid)}


# ---------- 돌아오기 ----------
def return_view(eid: int) -> dict | None:
    """가져간 것 가운데 다시 가져와야 하는 것. 먹고 쓰고 없어지는 것은 뺀다."""
    v = view(eid)
    if not v:
        return None
    back = [i for i in v["items"] if i["checked"] and i["meta"].get("bring_back") and i["meta"].get("kind") not in ("submit", "wear")]   # 낸 것과 입고 간 것은 묻지 않는다
    done = set(v["plus"]["returned"])
    items = [{"id": i["id"], "name": i["meta"].get("base") or i["name"], "returned": i["id"] in done,
              "tag": i["meta"].get("group") == "tag"} for i in back]
    left = [i["name"] for i in items if not i["returned"]]
    return {"id": v["id"], "title": v["title"], "date": v["date"], "items": items,
            "summary": {"counted": len(items), "returned": len(items) - len(left), "left": left}}


def set_skipped(eid: int, item_id: int, skipped: bool) -> dict | None:
    """'이번엔 빼기': 통신문에는 있지만 이번엔 안 가져가기로 한 것(예: 학교에 이미 있음). 금지와는 다르다."""
    ev = db.get_event(eid)
    if not ev or item_id not in {i["id"] for i in ev["items"]}:
        return None
    data = _event_data(eid)
    data["skipped"] = [x for x in data.get("skipped", []) if x != item_id] + ([item_id] if skipped else [])
    _event_save(eid, data)
    if skipped:
        db.set_item_checked(item_id, False)
    return view(eid)


def set_returned(eid: int, item_id: int, returned: bool) -> dict | None:
    r = return_view(eid)
    if not r or item_id not in {i["id"] for i in r["items"]}:
        return None                                      # 이 일정의 다시 가져올 물건이 아니다
    data = _event_data(eid)
    data["returned"] = [x for x in data["returned"] if x != item_id] + ([item_id] if returned else [])
    _event_save(eid, data)
    return return_view(eid)


def return_report(eid: int) -> dict | None:
    r = return_view(eid)
    if not r:
        return None
    s = r["summary"]
    title = f"🏠 집에 와서 가방을 확인했어요 · {r['title']}"
    body = f"가져옴 {s['returned']} · 아직 {len(s['left'])}" + (f" ({', '.join(s['left'])})" if s["left"] else " — 다 가져왔어요!")
    with db.tx() as con:
        con.execute("DELETE FROM notifications WHERE event_id=? AND kind='home'", (eid,))
        con.execute("INSERT INTO notifications(event_id,kind,fire_at,message) VALUES(?, 'home', ?, ?)",
                    (eid, now(), f"{title}\n{body}"))
    return {"title": title, "body": body, "summary": s}


def sweep(eid: int | None = None):
    """지운 일정·준비물에 딸린 추가 정보(근거 줄, 스티커, 상태)를 같이 지운다."""
    with db.tx() as con:
        if eid is not None:
            con.execute("DELETE FROM plus_event WHERE event_id=?", (eid,))
            con.execute("DELETE FROM plus_sticker WHERE event_id=?", (eid,))
        con.execute("DELETE FROM plus_event WHERE event_id NOT IN (SELECT id FROM events)")
        con.execute("DELETE FROM plus_sticker WHERE event_id NOT IN (SELECT id FROM events)")
        con.execute("DELETE FROM plus_item WHERE item_id NOT IN (SELECT id FROM items)")


def tone_previews(eid: int) -> dict | None:
    v = view(eid)
    if not v:
        return None
    out = {}
    for k, t in tone.TONES.items():                      # 말투마다 제목·메모와, 바깥 캘린더로 넘길 주소·파일
        b = calendar_out.bundle(v, k)
        out[k] = {"label": t["label"], "title": b["title"], "body": b["description"],
                  "google_url": b["google_url"], "ics": b["ics"], "filename": b["filename"]}
    return out

app/chaeng/simple_extract.py:
"""모델 없이 알림장 글에서 일정과 준비물을 뽑는 규칙(예시 모드, API 키가 없을 때의 대체 길).

extract.py(모델)와 같은 모양을 돌려준다. 정해진 꼴("준비물 : …", "일시 : …")만 읽는다.
못 읽은 것은 지어내지 않고 notes 에 '확인해 주세요'로 남긴다.
"""
from __future__ import annotations

import re
from datetime import date as Date, timedelta

SAMPLES = [
    {
        "key": "a", "title": "2학년 가을 현장체험학습 안내", "posted": None,
        "text": "2학년 가을 현장체험학습 안내\n1. 일시 : {d1} 09:00–14:30\n2. 장소 : ○○숲체험원\n"
                "3. 준비물 : 도시락, 마실 물(플라스틱 물통), 개인용 돗자리, 모자, 간식, 물티슈, 개인 약품(멀미약 등 필요한 학생), 우천 시 우산 또는 우의 등\n"
                "4. 유의 사항 : 유리병·탄산음료와 장난감, 귀중품은 가져오지 않습니다. 간편한 복장과 운동화를 착용합니다.\n"
                "---- 절 취 선 ----\n참가 신청서({d0}까지 제출)",
    },
    {
        "key": "b", "title": "4학년 현장체험학습(역사박물관) 안내", "posted": None,
        "text": "4학년 현장체험학습(역사박물관) 안내\n1. 일시 : {d1}, 8시 40분까지 교실로 등교\n"
                "2. 준비물 : 필기도구(연필 2자루, 지우개), 체험학습 활동지(지난주에 나눠 준 것), 물통, 작은 가방(백팩) 등\n"
                "3. 선택 : 얇은 겉옷, 손수건\n4. 소요 경비 : 체험비 12,000원(학교 예산 지원)\n"
                " ※ 체험비에 점심 식사 포함(도시락 지참하지 않음)\n5. 교통카드는 필요 없습니다(전세버스 이용).",
    },
    {
        "key": "c", "title": "[1학년 3반 알림장]", "posted": None,
        "text": "[1학년 3반 알림장]\n1. 내일은 가을 소풍입니다. 체육복 입고 오기\n2. 준비물: 도시락, 물, 돗자리, 물티슈, 비닐봉지 2장\n"
                "3. 과자는 한 봉지만! 탄산음료 X\n4. 비가 오면 교실에서 합니다(준비물 같음)\n5. 가정통신문 회신서 내일까지 내기\n"
                "6. 멀미하는 친구는 멀미약 먹고 오기, 개인 약은 가방에",
    },
]
_OUTDOOR = re.compile(r"체험|소풍|숲|운동회|체육대회|탐사|농장|야외|공원|수련|캠프|썰매|갯벌")


def sample(key: str = "a", today: Date | None = None) -> dict:
    """지어낸 예시 알림장(실제 학교 문서 아님). 날짜는 오늘 기준으로 채운다."""
    today = today or Date.today()
    s = next((x for x in SAMPLES if x["key"] == key), SAMPLES[0])
    d1, d0 = today + timedelta(days=1), today
    fmt = lambda d: f"{d.month}월 {d.day}일"
    return {"title": s["title"], "posted": today.isoformat(), "attachments": [], "url": f"sample:{s['key']}",
            "text": s["text"].format(d1=fmt(d1), d0=fmt(d0))}


_ITEM_HEAD = re.compile(r"^[\s\d.※\-•·*◦■□▶○]*(?:(?:학생|개인|학습|복장\s*및)\s*)*(?:준비물|챙길\s?것|지참물)\s*[:：]?\s*")


_BAN_PAREN = re.compile(r"\s*[(（][^()（）]*(?:불가|금지|안\s?됨|안\s?됩니다|않음|않습니다|하지\s?않|[X✕×])[^()（）]*[)）]\s*$")


def cut_note(body: str) -> str:
    """준비물 줄 안에서 괄호 밖의 ※나 ' * ' 뒤는 안내문이다. "간편 복장 등 ※실내 수영장에서 …" → "간편 복장 등" """
    depth = 0
    for i, ch in enumerate(body):
        if ch in "(（":
            depth += 1
        elif ch in ")）":
            depth = max(0, depth - 1)
        elif depth == 0 and (ch == "※" or (ch == "*" and i > 0 and body[i - 1] == " ")):
            return body[:i]
    return body


def split_items(chunk: str) -> list[str]:
    """쉼표로 나누되 괄호 안의 쉼표는 건드리지 않는다. 끝의 '등'과 금지 괄호는 뗀다."""
    out, buf, depth = [], "", 0
    for ch in cut_note(chunk):
        if ch in "(（":
            depth += 1
        elif ch in ")）":
            depth = max(0, depth - 1)
        if ch in ",、" and depth == 0:
            out.append(buf)
            buf = ""
        else:
            buf += ch
    out.append(buf)
    items = []
    for x in out:
        x = _BAN_PAREN.sub("", x.strip())             # "비닐 봉투 (장난감 등 불가)" → "비닐 봉투" (금지는 guard가 통신문 글에서 따로 읽음)
        x = re.sub(r"\s+등\s*[.]?\s*$", "", x).strip(" .")
        x = re.sub(r"만\s*준비$", "", x).strip()       # "음료수와 물만 준비" → "음료수와 물"
        x = re.sub(r"\s*착용$", "", x)                 # "운동화 착용" → "운동화"
        if x and x != "등":
            items.append(x)
    return items


def _date(m: re.Match, base: Date) -> Date | None:
    """'11월 20일' 또는 '2026년 11월 20일' → 날짜. 적힌 연도가 있으면 그대로, 없으면 기준일에서 가까운 앞날. 없는 날짜면 None."""
    year, month, day = m.group(1), int(m.group(2)), int(m.group(3))
    for y in ([int(year)] if year else [base.year, base.year + 1]):
        try:
            d = Date(y, month, day)
        except ValueError:
            continue
        if year or (base - d).days <= 60:
            return d
    return None


def extract(text: str, title: str | None = None, posted: str | None = None, today: Date | None = None) -> dict:
    today = today or Date.today()
    try:
        base = Date.fromisoformat((posted or "").replace(".", "-")[:10]) if posted else today
    except ValueError:
        base = today
    lines = [l.strip() for l in (text or "").splitlines() if l.strip()]
    if not lines:
        return {"summary": "읽을 글이 없어요", "events": [], "usage": {"input": 0, "output": 0, "model": "규칙(모델 호출 없음)"}}
    ttl = re.sub(r"\s*안내\s*$", "", (title or lines[0]).strip("[] ")).strip() or "학교 일정"
    if "알림장" in ttl:                              # "[1학년 3반 알림장] 내일은 가을 소풍입니다" → "1학년 3반 가을 소풍"
        m = re.search(r"(?:내일은|내일|오늘은)\s*([가-힣 ]{2,14}?)\s*(?:입니다|이에요|예요|가는 날)", text)
        if m:
            ttl = (ttl.replace("알림장", "").strip() + " " + m.group(1).strip()).strip()
    md = re.compile(r"(?:(\d{4})년\s*)?(\d{1,2})월\s*(\d{1,2})일")
    notes, when, start, end, loc = [], None, None, None, None
    for l in lines:
        if re.search(r"일시|날짜|언제", l) and md.search(l) and not when:
            when = _date(md.search(l), base)
            t = re.search(r"(\d{1,2}):(\d{2})\s*[–\-~]\s*(\d{1,2}):(\d{2})", l)
            if t:
                start, end = f"{int(t.group(1)):02d}:{t.group(2)}", f"{int(t.group(3)):02d}:{t.group(4)}"
            else:
                t = re.search(r"(\d{1,2})시\s*(\d{1,2})?분?", l)
                if t:
                    start = f"{int(t.group(1)):02d}:{int(t.group(2) or 0):02d}"
        if re.match(r"^[\d.\s]*장소", l):
            loc = re.split(r"[:：]", l, maxsplit=1)[-1].strip()
        if re.search(r"유의|주의|※|비가 오면", l) and not re.match(r"^[\d.\s]*(준비물|선택)", l) and not _ITEM_HEAD.match(l) and len(notes) < 3:
            notes.append(re.sub(r"^[\d.\s]*", "", l))
    if not when:
        if any("내일" in l for l in lines[:3]):
            when = base + timedelta(days=1)
        else:
            m = next((md.search(l) for l in lines if md.search(l) and not re.search(r"까지|제출|회신", l)), None)
            when = _date(m, base) if m else None
    if not when:
        when = base + timedelta(days=1)
        notes.append("날짜를 못 찾아 내일로 넣었어요. 확인해 주세요.")
    items: list[str] = []
    for l in lines:
        m_head = _ITEM_HEAD.match(l)
        if m_head:                                     # "5. 학생 준비물 : …", "※ 복장 및 준비물 : …", "4. 학생 준비물 수영복, …"
            body = re.sub(r"\s*[(（]\s*※?\s*(?:입장\s?제한|금지)[^)）]*[)）]?\s*$", "", l[m_head.end():])   # 줄 끝의 금지 괄호는 준비물이 아니다
            items += split_items(body)
        elif re.match(r"^[\d.\s]*선택\s*[:：]", l):
            items += [f"{x}(선택)" for x in split_items(re.split(r"[:：]", l, maxsplit=1)[-1])]
    for l in lines:                                   # 준비물 줄 밖에 있는 입고·신고 갈 것("체육복 입고 오기", "간편한 복장과 운동화를 착용합니다")
        if _ITEM_HEAD.match(l) or re.match(r"^[\d.\s]*선택", l):
            continue
        for seg in re.split(r"(?<=[.!?])\s+", l):
            if re.search(r"않|말아|마세요|금지|불가|안\s?됩|안\s?돼", seg):
                continue                               # "슬리퍼는 신고 오지 않습니다" 같은 금지 문장은 건너뛴다
            m = re.search(r"([가-힣 ]{2,24}?)\s*(?:을|를)?\s*입고\s*오기", seg)
            if m and not any(m.group(1).strip() in i for i in items):
                items.append(f"{m.group(1).strip()} 입고 오기")
                continue
            m = re.search(r"([가-힣 ]{2,24}?)\s*(?:을|를)\s*(?:착용|입고\s*(?:옵니다|와요|오세요|등교)|신고\s*(?:오기|옵니다|와요|오세요))", seg)
            if m:
                for name in re.split(r"\s*(?:,|와\s|과\s|및\s)\s*", re.sub(r"^.*[:：]\s*", "", m.group(1))):
                    name = name.strip()
                    if 1 < len(name) <= 12 and not any(name in i for i in items):
                        items.append(name)
    tgt = re.search(r"\d학년(?:\s*\d반)?", " ".join(lines[:2]))
    events = [{
        "title": ttl, "kind": "event", "date": when.isoformat(), "start_time": start, "end_time": end,
        "location": loc, "lat": None, "lon": None, "outdoor": bool(_OUTDOOR.search(" ".join(lines))) and not re.search(r"박물관|미술관|과학관|공연|실내|도서관", " ".join(lines)),
        "target": tgt.group(0) if tgt else None,
        "items": items, "ai_items": [], "notes": "\n".join(notes),
    }]
    for l in lines:                                   # 회신 마감은 따로 일정으로("11월 20일까지 제출", "내일까지 내기")
        if not re.search(r"까지\s*(제출|회신|내기|내\s?주)", l):
            continue
        m, rel = md.search(l), re.search(r"(오늘|내일|모레)\s*까지", l)
        due = _date(m, base) if m else base + timedelta(days={"오늘": 0, "내일": 1, "모레": 2}[rel.group(1)]) if rel else None
        if not due:
            notes.append("회신 마감 날짜를 못 읽었어요. 확인해 주세요.")
            events[0]["notes"] = "\n".join(notes)
            continue
        doc = re.search(r"(참가\s?신청서|회신서|신청서|동의서|확인서)", l)
        events.append({"title": f"{ttl} 회신 마감", "kind": "deadline", "date": due.isoformat(),
                       "start_time": None, "end_time": None, "location": None, "lat": None, "lon": None,
                       "outdoor": False, "target": None, "items": [doc.group(1) if doc else "회신서"], "ai_items": [], "notes": l})
    return {"summary": f"{ttl}: 준비물 {len(items)}개를 찾았어요 (규칙으로 읽은 예시 모드, 꼭 확인해 주세요)",
            "events": events, "usage": {"input": 0, "output": 0, "model": "규칙(모델 호출 없음)"}}

app/chaeng/tone.py:
"""달력·알림에 적는 글의 말투 틀. 숫자와 목록은 코드가 채우고 말투만 바뀐다(모델 호출 없음).

basic: 보통 말투 / cute: 귀엽게 / neat: 또박또박(모범생처럼)
"""
from __future__ import annotations

from datetime import date as Date

TONES = {
    "basic": {"label": "보통"},
    "cute": {"label": "귀엽게"},
    "neat": {"label": "또박또박"},
}


def _when(ev: dict) -> str:
    gap = (Date.fromisoformat(ev["date"]) - Date.today()).days
    return {0: "오늘", 1: "내일"}.get(gap, f"{int(ev['date'][5:7])}월 {int(ev['date'][8:10])}일")


def subject(name: str) -> str:
    """아이 이름에 주격 조사 붙이기: 하늘 → 하늘이가, 지우 → 지우가"""
    if not name:
        return "아이가"
    last = ord(name[-1])
    has_final = 0xAC00 <= last <= 0xD7A3 and (last - 0xAC00) % 28 != 0
    return name + ("이가" if has_final else "가")


def _names(items: list[dict], limit: int = 8) -> str:
    names = [i["name"] for i in items]
    return ", ".join(names[:limit]) + (f" 외 {len(names) - limit}개" if len(names) > limit else "")


def calendar_entry(ev: dict, tone: str = "basic") -> tuple[str, str]:
    """달력에 넣을 제목과 메모. ev 는 service.view() 결과."""
    req = [i for i in ev["items"] if not i.get("optional")]
    opt = [i for i in ev["items"] if i.get("optional") and not i.get("guardian")]
    ban = [f["name"] for f in ev.get("plus", {}).get("forbidden", [])]
    t = ev.get("start_time")
    grd = [i for i in ev["items"] if i.get("guardian")]           # 약처럼 보호자가 정할 것은 따로 적는다
    if tone == "cute":
        title = f"🎒 {ev['title']} 가는 날!"
        body = f"챙길 것 {len(req)}개: {_names(req)}"
        if opt:
            body += f"\n있으면 좋아요: {_names(opt, 4)}"
        if ban:
            body += f"\n이건 두고 가요 🙅 {', '.join(ban)}"
        if t:
            body += f"\n{t}까지 늦지 않게 출발~"
    elif tone == "neat":
        title = f"[준비물 {len(req)}] {ev['title']}"
        body = "\n".join(f"{n}. {i['name']}" for n, i in enumerate(req, 1))
        if opt:
            body += "\n(추천) " + _names(opt, 4)
        if ban:
            body += "\n(금지) " + ", ".join(ban)
        if t:
            body += f"\n(시작) {t}"
    else:
        title = f"{ev['title']} 준비물"
        body = f"준비물: {_names(req)}"
        if opt:
            body += f"\n추천: {_names(opt, 4)}"
        if ban:
            body += f"\n가져오지 않는 것: {', '.join(ban)}"
        if t:
            body += f"\n시작 {t}"
    if grd:
        body += f"\n보호자가 정할 것: {_names(grd, 3)}"
    return title, body


def kid_report(ev: dict, s: dict, profile: dict | None = None) -> tuple[str, str]:
    """아이가 가방을 싼 결과를 보호자 알림함에 남기는 글."""
    tone = (profile or {}).get("tone", "basic")
    who = subject((profile or {}).get("name") or "")
    left = f" ({', '.join(s['left'])})" if s["left"] else ""
    counts = f"준비물 {s['counted']} · 넣음 {s['packed']} · 아직 {len(s['left'])}{left}"
    if s["optional"]:
        counts += f" · 추천 {s['optional']} 중 {s['optional_packed']}"
    if s["open_alerts"]:
        counts += f" · 빼야 할 것: {', '.join(s['open_alerts'])}"
    if s["list_open"]:
        counts += " · 알림장 목록이 '등'으로 끝나요"
    if tone == "cute":
        title = f"🧒 {who} 가방 쌌어요! · {_when(ev)} {ev['title']}"
        body = ("다 챙겼지! 🎉 " if s["all_packed"] and not s["open_alerts"] else "") + counts
    elif tone == "neat":
        title = f"[가방 점검] {ev['title']} ({_when(ev)})"
        body = counts
    else:
        title = f"🧒 {who} 가방을 쌌어요 · {ev['title']}"
        body = counts
    return title, body

